<?php
$staff=in_array(role(),['admin','pengurus'],true);$edit=null;if($staff && get('edit')){$s=db()->prepare('SELECT * FROM pengumuman WHERE id=?');$s->execute([(int)get('edit')]);$edit=$s->fetch();}
if($staff){$rows=db()->query("SELECT p.*,u.nama pembuat FROM pengumuman p LEFT JOIN users u ON u.id=p.dibuat_oleh WHERE p.status<>'archived' ORDER BY p.created_at DESC LIMIT 150")->fetchAll();}
else {$rows=db()->query("SELECT p.*,u.nama pembuat FROM pengumuman p LEFT JOIN users u ON u.id=p.dibuat_oleh WHERE p.status='published' AND (p.ditampilkan_sampai IS NULL OR p.ditampilkan_sampai>=NOW()) ORDER BY p.prioritas DESC,p.tanggal_publish DESC LIMIT 100")->fetchAll();}
?>
<div class="page-heading"><div><h1>Pengumuman</h1><p><?= $staff?'Buat dan kelola informasi untuk seluruh warga.':'Informasi resmi dari pengurus lingkungan RT.' ?></p></div><?php if($staff): ?><a class="btn btn-army" href="<?= e(url('pengumuman',['new'=>1])) ?>"><i class="bi bi-plus-lg me-2"></i>Buat Pengumuman</a><?php endif; ?></div>
<?php if($staff && (get('new') || $edit)): ?><section class="panel-card mb-4"><div class="panel-card-header"><h2 class="panel-title"><?= $edit?'Edit Pengumuman':'Pengumuman Baru' ?></h2><a href="<?= e(url('pengumuman')) ?>" class="text-link">Tutup</a></div><div class="panel-card-body"><form method="post" action="index.php" class="row g-3" data-disable-submit><?= csrf_field() ?><input type="hidden" name="action" value="save_pengumuman"><input type="hidden" name="return_page" value="pengumuman"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><div class="col-md-8"><label class="form-label">Judul</label><input class="form-control" name="judul" value="<?= e($edit['judul']??'') ?>" required></div><div class="col-md-4"><label class="form-label">Prioritas</label><select class="form-select" name="prioritas"><option value="normal" <?= ($edit['prioritas']??'normal')==='normal'?'selected':'' ?>>Normal</option><option value="penting" <?= ($edit['prioritas']??'')==='penting'?'selected':'' ?>>Penting</option></select></div><div class="col-12"><label class="form-label">Ringkasan</label><input class="form-control" name="ringkasan" maxlength="500" value="<?= e($edit['ringkasan']??'') ?>"></div><div class="col-12"><label class="form-label">Isi pengumuman</label><textarea class="form-control" name="isi" rows="6" required><?= e($edit['isi']??'') ?></textarea></div><div class="col-md-4"><label class="form-label">Status publikasi</label><select class="form-select" name="status"><option value="draft" <?= ($edit['status']??'draft')==='draft'?'selected':'' ?>>Simpan sebagai draft</option><option value="published" <?= ($edit['status']??'')==='published'?'selected':'' ?>>Terbitkan</option></select></div><div class="col-12 d-flex justify-content-end gap-2"><a class="btn btn-outline-secondary" href="<?= e(url('pengumuman')) ?>">Batal</a><button class="btn btn-army">Simpan Pengumuman</button></div></form></div></section><?php endif; ?>
<div class="row g-3"><?php if(!$rows): ?><div class="col-12"><div class="panel-card empty-state"><i class="bi bi-megaphone"></i><strong>Belum ada pengumuman</strong><span>Pengumuman lingkungan akan ditampilkan di sini.</span></div></div><?php else: foreach($rows as $n): ?><div class="col-12"><article class="panel-card p-4"><div class="d-flex flex-wrap justify-content-between align-items-start gap-2"><div><div class="d-flex align-items-center gap-2 mb-2"><?= status_badge($n['status']) ?><?php if($n['prioritas']==='penting'): ?><span class="badge text-bg-warning">Penting</span><?php endif; ?></div><h2 class="h5 fw-bold mb-2"><?= e($n['judul']) ?></h2></div><small class="text-muted-2"><i class="bi bi-calendar3 me-1"></i><?= e(format_datetime($n['tanggal_publish'] ?: $n['created_at'])) ?></small></div><?php if($n['ringkasan']): ?><p class="text-muted-2 mb-2"><?= e($n['ringkasan']) ?></p><?php endif; ?><div class="announcement-body"><?= nl2br(e($n['isi'])) ?></div><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mt-3"><small class="text-muted-2">Dibuat oleh <?= e($n['pembuat']??'Pengurus') ?></small><?php if($staff): ?><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-army" href="<?= e(url('pengumuman',['edit'=>$n['id']])) ?>">Edit</a><?php if($n['status']!=='archived'): ?><form method="post" action="index.php"><?= csrf_field() ?><input type="hidden" name="action" value="delete_pengumuman"><input type="hidden" name="return_page" value="pengumuman"><input type="hidden" name="id" value="<?= $n['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Arsipkan pengumuman ini?">Arsipkan</button></form><?php endif; ?></div><?php endif; ?></div></article></div><?php endforeach; endif; ?></div>
